### Instruction:
Create an HTML form which accepts an input string and returns the longest word in the string

### Input:
Hello world!

### Response:
<html>
  <head>
    <title>Longest word finder</title>
    <script type="text/javascript">
      function longestWordFinder() {
        // Get user input
        const inputString = document.getElementById("inputString").value;

        // Split the input string into an array of words
        let words = inputString.split(" ");

        // Iterate through the words array and find the longest word
        let longestWord = words[0];
        for (let i = 1; i < words.length; i++) {
            if (words[i].length > longestWord.length)
                longestWord = words[i];
        }

        // Display the result
        document.getElementById("result").innerHTML = longestWord;
      } 
    </script>
  </head>
  <body>
    <h1>Longest Word Finder</h1>
    <input type="text" id="inputString" />
    <button type="submit" onclick="longestWordFinder()">Submit</button>
    <p>The longest word is: <span id="result"></span></p>
  </body>
</html>

