### Instruction:
Write an algorithm to find the maximum substring in the given string.

### Input:
abcadefghi

### Response:
def findMaxSubstring(string):
    max_len = 0
    max_substring = ""
    for i in range(len(string)):
        current_substring = []
        for j in range(i, len(string)):
            if string[j] not in current_substring:
                current_substring.append(string[j])
            else:
                break
        if len(current_substring) > max_len:
            max_len = len(current_substring)
            max_substring = ''.join(current_substring)
    return max_substring

