export async function generateProjects() {
  const { originUrl, headUrl } = await new Listr(
    [
      {
        title: 'Origin project',
        task: (ctx, task) =>
          task.newListr(
            (parent) => [
              {
                title: 'Resetting project',
                task: async () => {
                  await resetProject({
                    teamId: TEST_TEAM_NAME,
                    projectName: ORIGIN_PROJECT_NAME,
                    disableDeploymentProtection: true,
                  })
                },
              },
              {
                title: 'copying app',
                task: async () => {
                  await execa('cp', ['-f', '-R', appFolder, originAppFolder])
                },
              },
              {
                title: 'Set Next.js version in package.json',
                task: async () => {
                  await generatePackageJson(originAppFolder)
                },
              },
              {
                title: 'deploying project',
                task: async () => {
                  const url = await deployProject(
                    ORIGIN_PROJECT_NAME,
                    originAppFolder
                  )
                  ctx.originUrl = url
                },
              },
            ],
            { concurrent: false }
          ),
      },
      {
        title: 'Head project',
        task: (ctx, task) =>
          task.newListr(
            (parent) => [
              {
                title: 'Resetting project',
                task: async () => {
                  await resetProject({
                    teamId: TEST_TEAM_NAME,
                    projectName: HEAD_PROJECT_NAME,
                    disableDeploymentProtection: true,
                  })
                },
              },
              {
                title: 'copying app',
                task: async () => {
                  await execa('cp', ['-f', '-R', appFolder, headAppFolder])
                },
              },
              {
                title: 'pack local Next.js version',
                task: async () => {
                  await generatePackageJson(headAppFolder, true)
                },
              },
              {
                title: 'deploying project',
                task: async () => {
                  const url = await deployProject(
                    HEAD_PROJECT_NAME,
                    headAppFolder
                  )
                  ctx.headUrl = url
                },
              },
            ],
            { concurrent: false }
          ),
      },
    ],
    { concurrent: true }
  ).run()

  return [originUrl, headUrl]
}

export async function cleanupProjectFolders() {
  await Promise.all([
    execa('rm', ['-rf', originAppFolder]),
    execa('rm', ['-rf', headAppFolder]),
  ])
}

export async function deployProject(projectName, appFolder) {
  try {
    const vercelFlags = ['--scope', TEST_TEAM_NAME]
    const vercelEnv = { ...process.env, TOKEN: TEST_TOKEN }

    // link the project
    const linkRes = await execa(
      'vercel',
      ['link', '-p', projectName, '--confirm', ...vercelFlags],
      {
        cwd: appFolder,
        env: vercelEnv,
      }
    )

    if (linkRes.exitCode !== 0) {
      throw new Error(
        `Failed to link project ${linkRes.stdout} ${linkRes.stderr} (${linkRes.exitCode})`
      )
    }

    const deployRes = await execa(
      'vercel',
      [
        'deploy',
        '--build-env',
        'NEXT_PRIVATE_TEST_MODE=1',
        '--build-env',
        'NEXT_TELEMETRY_DISABLED=1',
        ...(VERCEL_EDGE_FUNCTIONS_BRIDGE_PKG
          ? [
              '--build-env',
              `VERCEL_EDGE_FUNCTIONS_BRIDGE_PKG=${VERCEL_EDGE_FUNCTIONS_BRIDGE_PKG}`,
            ]
          : []),
        '--force',
        ...vercelFlags,
        ...(forceCrash ? ['--env', 'CRASH_FUNCTION=1'] : []),
      ],
      {
        cwd: appFolder,
        env: vercelEnv,
      }
    )

    if (deployRes.exitCode !== 0) {
      throw new Error(
        `Failed to deploy project ${linkRes.stdout} ${linkRes.stderr} (${linkRes.exitCode})`
      )
    }

    return deployRes.stdout
  } catch (err) {
    console.log(red('Deployment failed: ', err))
    throw err
  }
}

const os = require('os')
const path = require('path')
const fs = require('fs/promises')

const errorsDir = path.join(__dirname, '.errors')

// This script checks for new error codes in .errors directory and consolidates them into errors.json.
// It will fail if new error codes are found, after consolidating them, to ensure error codes are
// properly reviewed and committed.
async function main() {
  // Check if .errors directory exists
  try {
    await fs.access(errorsDir)
  } catch {
    process.exit(0)
  }

  let existingErrors = {}

  // Load existing errors.json if it exists
  try {
    existingErrors = JSON.parse(
      await fs.readFile(path.join(__dirname, 'errors.json'), 'utf8')
    )
  } catch {
    // Start fresh if errors.json doesn't exist
  }

  // Calculate next error code
  const nextInitialCode =
    Object.keys(existingErrors).length > 0
      ? Math.max(...Object.keys(existingErrors).map(Number)) + 1
      : 1

  // Process new error files
  const errorFiles = [...(await fs.readdir(errorsDir))].map((file) =>
    path.join(errorsDir, file)
  )

  let newErrorCount = 0
  for (const file of errorFiles) {
    const { errorMessage } = JSON.parse(await fs.readFile(file, 'utf8'))

    // Check if message already exists
    const existingCode = Object.entries(existingErrors).find(
      ([_, msg]) => msg === errorMessage
    )?.[0]

    if (!existingCode) {
      // Only add if message is new
      const code = nextInitialCode + newErrorCount
      existingErrors[code] = errorMessage
      newErrorCount++
    }
  }

  // Write updated errors and cleanup
  await fs.writeFile(
    path.join(__dirname, 'errors.json'),
    JSON.stringify(existingErrors, null, 2) +
      // Formatters would add these anyway
      os.EOL
  )

  await fs.rm(errorsDir, { recursive: true, force: true })
  process.exit(1)
}

main().catch(console.error)

